'use client';
import React from 'react';

import EmojiPicker from 'emoji-picker-react';


// GitHub's fixed reaction set. allowExpandReactions={false} makes the
// compact bar terminal: there is no "+" and no full picker.
export type ShellProps = {
  /** The picker root: EmojiPicker, or a styled() wrapper of it. */
  Root?: React.ComponentType<React.ComponentProps<typeof EmojiPicker>>;
  className?: string;
};

export function Shell({ Root: RootComponent = EmojiPicker, className }: ShellProps) {
  return (
    <div className="gh-stage">
      <div className="gh-comment-header">
        <strong>octocat</strong> commented 3 hours ago
      </div>
      Repro is attached. Happens on every cold start since 2.4.0.
      <div className="gh-popover-label">Pick your reaction</div>
      <RootComponent         className={className}
        reactionsDefaultOpen
        allowExpandReactions={false}
        reactions={[
          '1f44d',
          '1f44e',
          '1f604',
          '1f389',
          '1f615',
          '2764-fe0f',
          '1f680',
          '1f440',
        ]}
      />
    </div>
  );
}

/* The surrounding mock app (shared by every stack variant). */
.gh-stage {
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', 'Noto Sans',
    Helvetica, Arial, sans-serif;
  width: 420px;
  padding: 16px;
  border: 1px solid #d0d7de;
  border-radius: 6px;
  background: #ffffff;
  color: #1f2328;
  font-size: 14px;
}
.gh-comment-header {
  margin: -16px -16px 12px;
  padding: 8px 16px;
  border-bottom: 1px solid #d0d7de;
  border-radius: 6px 6px 0 0;
  background: #f6f8fa;
  color: #59636e;
}
.gh-comment-header strong {
  color: #1f2328;
}
.gh-popover-label {
  margin: 14px 0 6px;
  color: #59636e;
  font-size: 12px;
}

/* GitHub Primer — issue/PR reactions: the fixed eight-reaction popover
   (no full picker), square-ish Primer surfaces and focus rings. */
/* Picker styles — the source of truth for every stack variant. */
.gh-picker {
  --epr-reactions-bg-color: #ffffff;
  --epr-bg-color: #ffffff;
  --epr-picker-border-color: #d0d7de;
  --epr-hover-bg-color: #eff2f5;
  --epr-hover-bg-color-reduced-opacity: #eff2f5;
  --epr-picker-border-radius: 6px;
  box-shadow: 0 8px 24px rgb(140 149 159 / 20%);
}
.gh-picker[data-epr-part='root'] {
  backdrop-filter: none;
}
.gh-picker [data-epr-part='reactions'] {
  padding: 0 4px;
}
.gh-picker [data-epr-part='reaction'] {
  border-radius: 6px;
}
.gh-picker [data-epr-part='reaction']:focus-visible {
  outline: 2px solid #0969da;
  outline-offset: -2px;
}

/* Generated by scripts/generateRecipes.mts from picker.css — do not edit. */
.picker {
  --epr-reactions-bg-color: #ffffff;
  --epr-bg-color: #ffffff;
  --epr-picker-border-color: #d0d7de;
  --epr-hover-bg-color: #eff2f5;
  --epr-hover-bg-color-reduced-opacity: #eff2f5;
  --epr-picker-border-radius: 6px;
  box-shadow: 0 8px 24px rgb(140 149 159 / 20%);
}
.picker[data-epr-part='root'] {
  backdrop-filter: none;
}
.picker [data-epr-part='reactions'] {
  padding: 0 4px;
}
.picker [data-epr-part='reaction'] {
  border-radius: 6px;
}
.picker [data-epr-part='reaction']:focus-visible {
  outline: 2px solid #0969da;
  outline-offset: -2px;
}
